# Implementation plans

Plans turn an accepted specification into a reviewable sequence of small,
verifiable changes. They explain how to build the behavior; the linked
specification remains the source of truth for what the behavior must be.

Use the same kebab-case stem as the specification. A useful plan includes:

- a link to the accepted specification;
- the goal, non-goals, and assumptions relevant to implementation;
- ordered tasks with exact file paths;
- a failing test before each behavior change;
- the minimal implementation needed to pass that test;
- documentation and public-export updates;
- focused and full verification commands;
- a completion checklist updated as tasks land.

Prefer tasks that can be implemented and reviewed independently. Include short
code snippets when they remove ambiguity, but do not paste entire future files
into the plan.

See [`example-retry-policy.md`](example-retry-policy.md) for a test-first sample.

//! Public contract smoke tests.
use std::collections::BTreeMap;
use tinysearch::{SearchConfig, SearchService, names};
#[test]
fn host_can_discover_search_interface() {
    assert_eq!(names::methods::LIST_TOOLS, "ListTools");
    assert!(
        SearchService::with_providers(SearchConfig::default(), BTreeMap::new())
            .list_tools()
            .tools
            .is_empty()
    );
}

//! Wire-format and credential-redaction tests.
use super::*;

#[test]
fn config_defaults_and_redacts_credentials() -> serde_json::Result<()> {
    let mut config = SearchConfig::default();
    config.backend.credential = Some("backend-secret".into());
    config.providers.insert(
        "parallel".into(),
        ProviderConfig {
            credential: Some("provider-secret".into()),
            ..ProviderConfig::default()
        },
    );
    let debug = format!("{config:?}");
    assert!(!debug.contains("backend-secret"));
    assert!(!debug.contains("provider-secret"));
    let decoded: SearchConfig = serde_json::from_value(serde_json::json!({}))?;
    assert!(decoded.enabled);
    assert_eq!(decoded.presentation.mode, PresentationMode::AllTools);
    Ok(())
}

#[test]
fn execution_wire_names_are_stable() -> serde_json::Result<()> {
    let request = ExecuteToolRequest {
        name: "parallel_search".into(),
        arguments: serde_json::json!({"query":"rust"}),
    };
    assert_eq!(
        serde_json::to_value(request)?,
        serde_json::json!({"name":"parallel_search","arguments":{"query":"rust"}})
    );
    Ok(())
}

#[test]
fn search_result_publication_is_optional_on_the_wire() -> serde_json::Result<()> {
    let old: SearchResult = serde_json::from_value(serde_json::json!({
        "title":"Old", "url":"https://example.test", "snippet":null
    }))?;
    assert_eq!(old.published, None);
    assert!(serde_json::to_value(&old)?.get("published").is_none());

    let dated: SearchResult = serde_json::from_value(serde_json::json!({
        "title":"Dated", "url":"https://example.test", "snippet":null,
        "published":"2026-01-02"
    }))?;
    assert_eq!(dated.published.as_deref(), Some("2026-01-02"));
    assert_eq!(serde_json::to_value(dated)?["published"], "2026-01-02");
    Ok(())
}

#[test]
fn provider_limits_round_trip_without_exposing_credential_in_debug() -> serde_json::Result<()> {
    let config: ProviderConfig = serde_json::from_value(serde_json::json!({
        "credential":"private-key", "max_results":12, "timeout_secs":8,
        "default_language":"fr"
    }))?;
    assert_eq!(config.max_results, Some(12));
    assert_eq!(config.timeout_secs, Some(8));
    assert_eq!(config.default_language.as_deref(), Some("fr"));
    let serialized = serde_json::to_value(&config)?;
    assert_eq!(serialized["max_results"], 12);
    assert_eq!(serialized["timeout_secs"], 8);
    assert_eq!(serialized["default_language"], "fr");
    assert!(!format!("{config:?}").contains("private-key"));
    let legacy: ProviderConfig =
        serde_json::from_value(serde_json::json!({"credential":"private-key"}))?;
    assert_eq!(legacy.max_results, None);
    assert_eq!(legacy.timeout_secs, None);
    assert_eq!(legacy.default_language, None);
    Ok(())
}

//! Unit tests for the contract version and its bind rule.

use super::{CONTRACT_VERSION, binds, is_compatible};

#[test]
fn the_shipped_contract_version_is_pinned() {
    assert_eq!(CONTRACT_VERSION, (1, 0));
}

#[test]
fn the_contract_binds_to_itself() {
    assert!(is_compatible(CONTRACT_VERSION));
}

#[test]
fn a_newer_minor_on_the_module_side_binds() {
    assert!(is_compatible((1, 1)));
    assert!(is_compatible((1, 97)));
}

#[test]
fn an_older_minor_on_the_module_side_is_rejected() {
    // A host built against 1.4 cannot call a 1.2 module: the members it names
    // may not be served.
    assert!(!binds((1, 4), (1, 2)));
    assert!(binds((1, 4), (1, 4)));
}

#[test]
fn a_different_major_is_rejected() {
    assert!(!is_compatible((0, 0)));
    assert!(!is_compatible((2, 0)));
    assert!(!is_compatible((2, 97)));
}

//! Provider-independent service tests.
use super::*;
use crate::SearchStatus;
use serde_json::json;
use tinysearch_bus::{PresentationConfig, SearchStatus as Status};

struct MockProvider;
impl SearchProvider for MockProvider {
    fn execute<'a>(
        &'a self,
        _config: &'a ProviderConfig,
        _backend: &'a BackendConfig,
        _request: &'a ExecuteToolRequest,
    ) -> ProviderFuture<'a> {
        Box::pin(async {
            Ok(ExecuteToolResponse {
                provider: "ignored".into(),
                results: vec![],
                citations: vec![],
                answer: None,
                status: Status::Empty,
                provider_data: None,
            })
        })
    }
}
fn service(mode: PresentationMode) -> SearchService {
    let mut config = SearchConfig {
        presentation: PresentationConfig {
            mode,
            provider: None,
        },
        ..SearchConfig::default()
    };
    config.backend.credential = Some("test-key".into());
    config.providers.insert(
        "parallel".into(),
        ProviderConfig {
            route: ProviderRoute::Backend,
            ..ProviderConfig::default()
        },
    );
    config.providers.insert(
        "searxng".into(),
        ProviderConfig {
            base_url: Some("http://127.0.0.1:8080".into()),
            ..ProviderConfig::default()
        },
    );
    let providers: BTreeMap<String, Arc<dyn SearchProvider>> = [
        (
            "parallel".into(),
            Arc::new(MockProvider) as Arc<dyn SearchProvider>,
        ),
        (
            "searxng".into(),
            Arc::new(MockProvider) as Arc<dyn SearchProvider>,
        ),
    ]
    .into();
    SearchService::with_providers(config, providers)
}
