#[test]
fn schema_validation_checks_arrays_enums_and_bounds() {
    let tool = ToolSpec {
        name: "fixture".into(),
        description: String::new(),
        parameters: json!({
            "type":"object",
            "properties":{
                "mode":{"type":"string","enum":["web","news"]},
                "limit":{"type":"integer","minimum":1,"maximum":10},
                "tags":{"type":"array","minItems":1,"maxItems":2,"items":{"type":"string","minLength":2}}
            },
            "required":["mode","limit","tags"],
            "additionalProperties":false
        }),
    };
    assert_eq!(
        validate_arguments(&tool, &json!({"mode":"web","limit":2,"tags":["rs"]})),
        Ok(())
    );
    for value in [
        json!({"mode":"images","limit":2,"tags":["rs"]}),
        json!({"mode":"web","limit":0,"tags":["rs"]}),
        json!({"mode":"web","limit":11,"tags":["rs"]}),
        json!({"mode":"web","limit":2.5,"tags":["rs"]}),
        json!({"mode":"web","limit":2,"tags":[]}),
        json!({"mode":"web","limit":2,"tags":["rs","go","js"]}),
        json!({"mode":"web","limit":2,"tags":["x"]}),
        json!({"mode":"web","limit":2,"tags":[8]}),
    ] {
        assert_eq!(
            validate_arguments(&tool, &value),
            Err(Error::InvalidArguments),
            "{value}"
        );
    }
}

#[test]
fn direct_provider_without_credential_is_hidden() {
    struct Keyed;
    impl SearchProvider for Keyed {
        fn execute<'a>(
            &'a self,
            _config: &'a ProviderConfig,
            _backend: &'a BackendConfig,
            _request: &'a ExecuteToolRequest,
        ) -> ProviderFuture<'a> {
            Box::pin(async { Err(Error::Provider("unreachable".into())) })
        }
    }
    let mut config = SearchConfig::default();
    config
        .providers
        .insert("parallel".into(), ProviderConfig::default());
    let mut providers: BTreeMap<String, Arc<dyn SearchProvider>> = BTreeMap::new();
    providers.insert("parallel".into(), Arc::new(Keyed));
    assert!(
        SearchService::with_providers(config.clone(), providers.clone())
            .list_tools()
            .tools
            .is_empty()
    );
    config.providers.insert(
        "parallel".into(),
        ProviderConfig {
            route: ProviderRoute::Backend,
            ..ProviderConfig::default()
        },
    );
    config.backend.credential = Some("secret".into());
    assert_eq!(
        SearchService::with_providers(config, providers)
            .list_tools()
            .tools
            .len(),
        6
    );
}

#[test]
fn schema_validation_checks_nested_objects_oneof_and_exclusive_bounds() {
    let tool = ToolSpec {
        name: "fixture".into(),
        description: String::new(),
        parameters: json!({
            "type":"object",
            "properties":{
                "choice":{"oneOf":[{"type":"string","enum":["fast"]},{"type":"integer","minimum":1}]},
                "score":{"type":"number","exclusiveMinimum":0,"exclusiveMaximum":1},
                "details":{"type":"object","required":["active"],"properties":{"active":{"type":"boolean"}},"additionalProperties":false},
                "empty":{"type":"null"}
            },
            "required":["choice","score","details","empty"],
            "additionalProperties":{"type":"string","maxLength":3}
        }),
    };
    assert_eq!(
        validate_arguments(
            &tool,
            &json!({"choice":"fast","score":0.5,"details":{"active":true},"empty":null,"tag":"ok"})
        ),
        Ok(())
    );
    for arguments in [
        json!({"choice":"slow","score":0.5,"details":{"active":true},"empty":null}),
        json!({"choice":0,"score":0.5,"details":{"active":true},"empty":null}),
        json!({"choice":"fast","score":0,"details":{"active":true},"empty":null}),
        json!({"choice":"fast","score":1,"details":{"active":true},"empty":null}),
        json!({"choice":"fast","score":0.5,"details":{},"empty":null}),
        json!({"choice":"fast","score":0.5,"details":{"active":true,"extra":1},"empty":null}),
        json!({"choice":"fast","score":0.5,"details":{"active":"yes"},"empty":null}),
        json!({"choice":"fast","score":0.5,"details":{"active":true},"empty":false}),
        json!({"choice":"fast","score":0.5,"details":{"active":true},"empty":null,"tag":"long"}),
    ] {
        assert_eq!(
            validate_arguments(&tool, &arguments),
            Err(Error::InvalidArguments),
            "{arguments}"
        );
    }
}

#[tokio::test]
async fn service_rejects_disabled_and_unknown_router_target() {
    let mut disabled = service(PresentationMode::AllTools);
    disabled.config.enabled = false;
    assert_eq!(
        disabled
            .execute_tool(ExecuteToolRequest {
                name: "parallel_search".into(),
                arguments: json!({"objective":"test"})
            })
            .await
            .err(),
        Some(Error::Disabled)
    );
    let router = service(PresentationMode::Router);
    assert_eq!(
        router
            .execute_tool(ExecuteToolRequest {
                name: "other".into(),
                arguments: json!({"query":"test"})
            })
            .await
            .err(),
        Some(Error::UnavailableTool("other".into()))
    );
    assert_eq!(
        router
            .execute_tool(ExecuteToolRequest {
                name: "search".into(),
                arguments: json!({"query":"test","provider":"missing"})
            })
            .await
            .err(),
        Some(Error::UnavailableProvider("missing".into()))
    );
}

use super::*;
use tokio::{
    io::{AsyncReadExt, AsyncWriteExt},
    net::TcpListener,
};

type TestResult<T> = std::result::Result<T, Box<dyn std::error::Error + Send + Sync>>;

async fn mock(
    status: u16,
    response: Value,
) -> TestResult<(String, tokio::task::JoinHandle<TestResult<String>>)> {
    let listener = TcpListener::bind("127.0.0.1:0").await?;
    let address = format!("http://{}", listener.local_addr()?);
    let task = tokio::spawn(async move {
        let (mut stream, _) = listener.accept().await?;
        let mut data = vec![0; 65536];
        let mut used = 0;
        loop {
            let read = stream.read(&mut data[used..]).await?;
            if read == 0 {
                break;
            }
            used += read;
            if let Some(end) = data[..used].windows(4).position(|w| w == b"\r\n\r\n") {
                let head = String::from_utf8_lossy(&data[..end + 4]);
                let length: usize = head
                    .lines()
                    .find_map(|l| {
                        l.to_ascii_lowercase()
                            .strip_prefix("content-length: ")
                            .and_then(|v| v.trim().parse().ok())
                    })
                    .unwrap_or(0);
                if used >= end + 4 + length {
                    break;
                }
            }
        }
        let request = String::from_utf8_lossy(&data[..used]).into_owned();
        let body = response.to_string();
        let reply = format!(
            "HTTP/1.1 {status} Test\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",
            body.len()
        );
        stream.write_all(reply.as_bytes()).await?;
        Ok(request)
    });
    Ok((address, task))
}
async fn mock_sequence(
    responses: Vec<Value>,
) -> TestResult<(String, tokio::task::JoinHandle<TestResult<Vec<String>>>)> {
    let listener = TcpListener::bind("127.0.0.1:0").await?;
    let address = format!("http://{}", listener.local_addr()?);
    let task = tokio::spawn(async move {
        let mut requests = Vec::new();
        for response in responses {
            let (mut stream, _) = listener.accept().await?;
            let mut data = vec![0; 8192];
            let used = stream.read(&mut data).await?;
            requests.push(String::from_utf8_lossy(&data[..used]).into_owned());
            let body = response.to_string();
            let reply = format!(
                "HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",
                body.len()
            );
            stream.write_all(reply.as_bytes()).await?;
        }
        Ok(requests)
    });
    Ok((address, task))
}
fn request(name: &str, arguments: Value) -> ExecuteToolRequest {
    ExecuteToolRequest {
        name: name.into(),
        arguments,
    }
}
fn backend(base_url: String, auth_mode: BackendAuthMode) -> BackendConfig {
    BackendConfig {
        base_url: Some(base_url),
        credential: Some("secret-token".into()),
        sdk_name: Some("openhuman".into()),
        auth_mode,
    }
}

#[test]
fn normalization_fills_limit_with_valid_results_after_invalid_entries() {
    let mut items = vec![json!({"title":"missing URL"}); 20];
    items.extend(
        (0..25).map(
            |n| json!({"url":format!("https://example.test/{n}"),"title":format!("Result {n}")}),
        ),
    );
    let response = normalize("tavily", "tavily_search", &json!({"results":items}));
    assert_eq!(response.results.len(), MAX_RESULTS);
    assert_eq!(response.results[0].url, "https://example.test/0");
    assert_eq!(response.results[19].url, "https://example.test/19");
    assert_eq!(response.citations.len(), MAX_RESULTS);
}

#[test]
fn provider_urls_reject_credentials_queries_and_non_http_schemes() -> TestResult<()> {
    for base in [
        "not a url",
        "ftp://example.test",
        "https://user@example.test",
        "https://example.test/?key=secret",
        "https://example.test/#fragment",
    ] {
        assert_eq!(
            direct_url(Some(base), "https://fallback.test", "/search")
                .err()
                .ok_or("expected provider error")?,
            Error::Provider("invalid provider URL".into())
        );
    }
    assert_eq!(
        direct_url(None, "https://example.test/root/", "/search")?,
        "https://example.test/root/search"
    );
    assert_eq!(
        backend_url(&BackendConfig::default(), "/search")
            .err()
            .ok_or("expected provider error")?,
        Error::Provider("backend URL unavailable".into())
    );
    Ok(())
}

#[tokio::test]
async fn backend_reports_rejected_failed_and_running_tasks() -> TestResult<()> {
    for (payload, expected_error, expected_status) in [
        (
            json!({"success":false,"data":{"secret":"body"}}),
            Some(Error::Provider("backend rejected provider request".into())),
            None,
        ),
        (
            json!({"success":true,"data":{"status":{"state":"failed"}}}),
            Some(Error::Provider("provider task failed".into())),
            None,
        ),
        (
            json!({"success":true,"data":{"status":"running"}}),
            None,
            Some(SearchStatus::InProgress),
        ),
    ] {
        let (url, server) = mock(200, payload).await?;
        let provider = BuiltinProvider {
            name: "tinyfish",
            client: Client::new(),
        };
        let result = provider
            .run(
                &ProviderConfig {
                    route: ProviderRoute::Backend,
                    ..ProviderConfig::default()
                },
                &backend(url, BackendAuthMode::Session),
                &request("tinyfish_search", json!({"query":"test"})),
            )
            .await;
        server.await??;
        assert!(expected_error.is_some() ^ expected_status.is_some());
        match (expected_error, expected_status) {
            (Some(error), None) => {
                assert_eq!(result.err().ok_or("expected provider error")?, error);
            }
            (None, Some(status)) => assert_eq!(result?.status, status),
            _ => {}
        }
    }
    Ok(())
}

#[tokio::test]
async fn provider_rejects_unknown_provider_tool_and_invalid_arguments() -> TestResult<()> {
    let config = ProviderConfig::default();
    let backend = BackendConfig::default();
    for (name, request_name, arguments, expected) in [
        (
            "unknown",
            "search",
            json!({}),
